function [n, v] = domain(x)
%DOMAIN  Outside the real domain sqrt, asin, acos, log, log10, log2 and pow give nan in every translation, as C's, Rust's and the
%   interpreter's do (MATLAB's own are complex there: its runtime's asils.pc.sqrt_ and the rest give nan). Which are nan, as
%   bits, and a value from inside the domain.
%   x: real[1] (passed a plain number)
%   returns n: int (passed a whole number)
%   returns v: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    n = 0;
    v = 0;
    n = 0;
    if isnan(asils.pc.sqrt_(x))
        n = (n + 1);
    end
    if isnan(asils.pc.asin_(x))
        n = (n + 2);
    end
    if isnan(asils.pc.acos_(x))
        n = (n + 4);
    end
    if isnan(asils.pc.log_(x))
        n = (n + 8);
    end
    if isnan(asils.pc.log10_(x))
        n = (n + 16);
    end
    if isnan(asils.pc.log2_(x))
        n = (n + 32);
    end
    if isnan(asils.pc.pow_(x, 0.5))
        n = (n + 64);
    end
    v = asils.pc.choose((x >= 0), (asils.pc.sqrt_(x) + asils.pc.log_((x + 1))), asils.pc.acos_((x / 3)));
end
